import {
  createContext,
  type ComponentType,
  type ReactNode,
  useContext,
  useMemo,
  useState,
} from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Activity, Library, Menu, Radio, Settings, X } from "lucide-react";
import "./index.css";
import { usePolling } from "./hooks/usePolling";

type PageKey = "library" | "broadcast" | "status" | "settings";

type SystemTone = "success" | "warning" | "danger" | "info";

type SystemState = {
  tone: SystemTone;
  label: string;
  detail: string;
  lastUpdatedAt?: string;
};

type PollingSnapshot = Partial<{
  systemTone: SystemTone;
  tone: SystemTone;
  status: string;
  message: string;
  detail: string;
  isOnline: boolean;
  activeJobs: number;
  lastUpdatedAt: string;
  error: Error | string | null;
}>;

type NavItem = {
  key: PageKey;
  label: string;
  description: string;
  icon: ComponentType<{ className?: string; "aria-hidden"?: boolean }>;
};

const navItems: NavItem[] = [
  {
    key: "library",
    label: "素材",
    description: "直播素材池",
    icon: Library,
  },
  {
    key: "broadcast",
    label: "开播",
    description: "无人直播编排",
    icon: Radio,
  },
  {
    key: "status",
    label: "状态",
    description: "任务与系统状态",
    icon: Activity,
  },
  {
    key: "settings",
    label: "设置",
    description: "账号与偏好",
    icon: Settings,
  },
];

const pageMeta: Record<
  PageKey,
  {
    eyebrow: string;
    title: string;
    summary: string;
  }
> = {
  library: {
    eyebrow: "Material Command Center",
    title: "素材中控",
    summary: "统一管理无人直播素材、脚本片段、商品卡与开播前检查项。",
  },
  broadcast: {
    eyebrow: "Live Automation",
    title: "开播控制台",
    summary: "编排无人直播流程，快速完成场景、素材、话术与节奏确认。",
  },
  status: {
    eyebrow: "System Health",
    title: "运行状态",
    summary: "查看轮询状态、任务队列、直播链路与异常提醒。",
  },
  settings: {
    eyebrow: "Workspace Settings",
    title: "系统设置",
    summary: "配置品牌、通知、权限、默认开播参数与自动化策略。",
  },
};

const toneClassName: Record<SystemTone, string> = {
  success: "bg-success shadow-[0_0_0_4px_color-mix(in_srgb,var(--success)_16%,transparent)]",
  warning: "bg-warning shadow-[0_0_0_4px_color-mix(in_srgb,var(--warning)_16%,transparent)]",
  danger: "bg-danger shadow-[0_0_0_4px_color-mix(in_srgb,var(--danger)_16%,transparent)]",
  info: "bg-info shadow-[0_0_0_4px_color-mix(in_srgb,var(--info)_16%,transparent)]",
};

const SystemContext = createContext<SystemState | null>(null);

function useSystem() {
  const context = useContext(SystemContext);

  if (!context) {
    throw new Error("useSystem must be used inside SystemContext.Provider");
  }

  return context;
}

function normalizeSystemState(snapshot: PollingSnapshot): SystemState {
  const hasError = Boolean(snapshot.error);
  const tone =
    snapshot.systemTone ??
    snapshot.tone ??
    (hasError ? "danger" : snapshot.isOnline === false ? "warning" : "success");

  const label =
    snapshot.status ??
    (tone === "success"
      ? "系统在线"
      : tone === "warning"
        ? "连接波动"
        : tone === "danger"
          ? "需要处理"
          : "同步中");

  const errorMessage =
    snapshot.error instanceof Error ? snapshot.error.message : snapshot.error;

  const detail =
    snapshot.detail ??
    snapshot.message ??
    errorMessage ??
    (typeof snapshot.activeJobs === "number"
      ? `${snapshot.activeJobs} 个任务正在运行`
      : "轮询服务已接入，等待实时数据更新");

  return {
    tone,
    label,
    detail,
    lastUpdatedAt: snapshot.lastUpdatedAt,
  };
}

export default function App() {
  const polling = usePolling() as PollingSnapshot;
  const system = useMemo(() => normalizeSystemState(polling), [polling]);
  const [activePage, setActivePage] = useState<PageKey>("library");
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  function handleNavigate(page: PageKey) {
    setActivePage(page);
    setIsSidebarOpen(false);
  }

  return (
    <SystemContext.Provider value={system}>
      <a
        href="#main-content"
        className="sr-only z-50 rounded-button bg-accent px-4 py-3 text-sm font-semibold text-bg-deep shadow-[0_12px_30px_color-mix(in_srgb,var(--accent)_22%,transparent)] transition focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:outline-none focus:ring-2 focus:ring-accent-hover focus:ring-offset-2 focus:ring-offset-bg-deep"
      >
        跳到主要内容
      </a>

      <div className="min-h-screen bg-bg-page text-text-primary">
        <MobileTopbar
          isSidebarOpen={isSidebarOpen}
          onToggle={() => setIsSidebarOpen((value) => !value)}
        />

        <div className="md:grid md:min-h-screen md:grid-cols-[var(--sidebar-width)_1fr]">
          <Sidebar
            activePage={activePage}
            isOpen={isSidebarOpen}
            onNavigate={handleNavigate}
            onClose={() => setIsSidebarOpen(false)}
          />

          {isSidebarOpen ? (
            <button
              type="button"
              aria-label="关闭侧边栏遮罩"
              className="fixed inset-0 z-30 bg-bg-deep/70 backdrop-blur-sm md:hidden"
              onClick={() => setIsSidebarOpen(false)}
            />
          ) : null}

          <main
            id="main-content"
            tabIndex={-1}
            className="min-h-screen px-4 pb-8 pt-20 outline-none sm:px-6 md:px-8 md:py-8 lg:px-10"
          >
            <Header activePage={activePage} />

            <AnimatePresence mode="wait">
              <motion.div
                key={activePage}
                initial={{ opacity: 0, y: 14 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{
                  duration: 0.3,
                  ease: [0.16, 1, 0.3, 1],
                }}
                className="mt-8"
              >
                <PageContent activePage={activePage} />
              </motion.div>
            </AnimatePresence>
          </main>
        </div>
      </div>
    </SystemContext.Provider>
  );
}

function MobileTopbar({
  isSidebarOpen,
  onToggle,
}: {
  isSidebarOpen: boolean;
  onToggle: () => void;
}) {
  return (
    <header className="fixed inset-x-0 top-0 z-40 flex h-16 items-center justify-between border-b border-border bg-bg-deep/86 px-4 backdrop-blur-xl md:hidden">
      <div className="flex items-center gap-3">
        <LogoMark />
        <div>
          <p className="text-sm font-semibold tracking-tight text-text-primary">
            PHS 中控
          </p>
          <p className="text-xs text-text-muted">无人直播素材系统</p>
        </div>
      </div>

      <button
        type="button"
        aria-label={isSidebarOpen ? "关闭侧边栏" : "打开侧边栏"}
        aria-expanded={isSidebarOpen}
        className="inline-flex size-10 items-center justify-center rounded-button border border-border bg-bg-raised text-text-primary transition hover:border-border-strong hover:bg-[color-mix(in_srgb,var(--bg-raised)_88%,white_12%)] focus:outline-none focus:ring-2 focus:ring-accent"
        onClick={onToggle}
      >
        {isSidebarOpen ? (
          <X className="size-5" aria-hidden />
        ) : (
          <Menu className="size-5" aria-hidden />
        )}
      </button>
    </header>
  );
}

function Sidebar({
  activePage,
  isOpen,
  onNavigate,
  onClose,
}: {
  activePage: PageKey;
  isOpen: boolean;
  onNavigate: (page: PageKey) => void;
  onClose: () => void;
}) {
  return (
    <aside
      className={[
        "fixed inset-y-0 left-0 z-40 flex w-sidebar flex-col border-r border-border bg-bg-deep px-4 py-5 transition-transform duration-300 ease-impeccable md:sticky md:top-0 md:z-auto md:h-screen md:translate-x-0",
        isOpen ? "translate-x-0" : "-translate-x-full",
      ].join(" ")}
      aria-label="主导航"
    >
      <div className="flex items-center justify-between gap-3 px-1">
        <div className="flex items-center gap-3">
          <LogoMark />
          <div>
            <p className="text-sm font-semibold tracking-tight text-text-primary">
              PHS 中控
            </p>
            <p className="text-xs text-text-muted">无人直播素材系统</p>
          </div>
        </div>

        <button
          type="button"
          aria-label="关闭侧边栏"
          className="inline-flex size-9 items-center justify-center rounded-button border border-border text-text-muted transition hover:border-border-strong hover:text-text-primary focus:outline-none focus:ring-2 focus:ring-accent md:hidden"
          onClick={onClose}
        >
          <X className="size-4" aria-hidden />
        </button>
      </div>

      <nav className="mt-8 flex flex-1 flex-col gap-2">
        {navItems.map((item) => (
          <SidebarButton
            key={item.key}
            item={item}
            isActive={activePage === item.key}
            onClick={() => onNavigate(item.key)}
          />
        ))}
      </nav>

      <SidebarFooter />
    </aside>
  );
}

function SidebarButton({
  item,
  isActive,
  onClick,
}: {
  item: NavItem;
  isActive: boolean;
  onClick: () => void;
}) {
  const Icon = item.icon;

  return (
    <button
      type="button"
      aria-current={isActive ? "page" : undefined}
      className={[
        "group flex w-full items-center gap-3 rounded-card border px-3 py-3 text-left transition duration-200 ease-impeccable focus:outline-none focus:ring-2 focus:ring-accent",
        isActive
          ? "border-accent/60 bg-[color-mix(in_srgb,var(--accent)_14%,var(--bg-raised))] text-text-primary shadow-[0_14px_36px_color-mix(in_srgb,var(--accent)_12%,transparent)]"
          : "border-transparent text-text-muted hover:border-border hover:bg-bg-raised hover:text-text-primary",
      ].join(" ")}
      onClick={onClick}
    >
      <span
        className={[
          "inline-flex size-10 shrink-0 items-center justify-center rounded-button border transition",
          isActive
            ? "border-accent/50 bg-accent text-bg-deep"
            : "border-border bg-bg-page text-text-muted group-hover:border-border-strong group-hover:text-text-primary",
        ].join(" ")}
      >
        <Icon className="size-5" aria-hidden />
      </span>

      <span className="min-w-0">
        <span className="block text-sm font-semibold">{item.label}</span>
        <span className="mt-0.5 block truncate text-xs text-text-muted">
          {item.description}
        </span>
      </span>
    </button>
  );
}

